import { NEURON_ACCURACY_LIMIT } from '06_shared/runtimeConfig/common/config';
// Прогноз тренду біткоїна: напрям — тоном (bull/bear), сила — насиченістю.
// За межею точності нейромережі — сильний сигнал (суцільна заливка), всередині —
// слабкий (приглушений фон), рівно нуль — нейтрально. Межа сувора: 0.85 — ще слабкий.
export const predictionTone = (trend) => {
    if (trend === 0) {
        return { tone: 'neutral', emphasis: 'soft' };
    }
    return {
        tone: trend > 0 ? 'bull' : 'bear',
        emphasis: Math.abs(trend) > NEURON_ACCURACY_LIMIT ? 'strong' : 'soft',
    };
};
